mapper.select:
select h.recalc_hist_id as "recalcHistId", h.job_id as "jobId", h.target_user_id as "targetUserId", case when k.name is not null then k.name else u.login_id end as "targetUserName", h.evaluation_year as "evaluationYear", h.formula_version_id as "formulaVersionId", h.target_scope as "targetScope", h.changed_count as "changedCount", h.before_total_score as "beforeTotalScore", h.after_total_score as "afterTotalScore", h.executed_at as "executedAt", h.criteria_detail as "criteriaDetail", h.target_change_summary_json::text as "targetChangeSummaryJson", h.request_id as "requestId", '재계산 이력은 조회 전용이며 재계산 실행 CTA 또는 점수 수정 기능을 제공하지 않습니다.' as "readOnlyNotice" from biz_recalc_hist h join users u on u.user_id = h.target_user_id left join korus_personnel_snapshots k on k.employee_no = u.employee_no where h.recalc_hist_id = #{recalcHistId}
and h.organization_code = #{organizationCode}
limit 1
